def base(name="gate-triage", owner=OWNER) -> dict:
    return {
        "name": name, "description": "Reads a failed run and proposes a fix.", "owner": owner, "kind": "event",
        "identity": {"type": "workload", "serviceAccount": f"autopilot-runs/{name}"},
        "profile": {"tierCeiling": "T1", "tools": ["glidepath.runs.list", "repo.file.get", "repo.pr.open"],
                    "glidepath": {"apps": ["gate-api"]}, "repos": {"allow": ["acme/gate-api"]}, "models": ["claude-sonnet-5-5"],
                    "network": "clearance+model", "compute": "small",
                    "limits": {"ttlMinutes": 20, "toolCalls": 60, "githubCalls": 40, "openPrs": 1, "modelTokens": 400000, "children": 0}},
        "runtime": {"image": IMG, "framework": "generic", "instructions": "Find why the run failed."},
        "triggers": [{"type": "event", "source": "glidepath", "bindingKey": "gate-api.pipelinerun.finished",
                      "match": {"subject.content.outcome": "failure"}, "maxPerHour": 4}],
    }


def bundled_defs() -> dict[str, dict]:
    docs = {}
    for n in BUNDLED:
        d = base(n, owner="group:default/team-platform")
        d["description"] = f"The platform's {n}."
        d["kind"] = "task"
        d["identity"] = {"type": "delegated"}
        d["triggers"] = [{"type": "manual"}]
        docs[n] = d
    return docs


# -- the decision of one pinned file ------------------------------------------------------------------------------------------

class _NoGH:
    pass


def decide(text: str, xr_name: str, owner: str, reserved=tuple(BUNDLED)) -> dict:
    """What the loader makes of one pinned file: its text through AgentXRs._decide, then defn.from_pin."""
    src = defn.Source("cluster", repo=REPO, path=f"agents/{xr_name}.yaml", commit=COMMIT, namespace=NS, xr=xr_name)
    ld = AgentXRs.__new__(AgentXRs)
    ld.now = lambda: T0
    doc, reason, _ = ld._decide({"type": "file", "content": text}, src)
    if reason is not None:
        return {"rejected": reason}
    out = defn.from_pin(doc, src, owner=owner, reserved={n: 1 for n in reserved})
    if isinstance(out, defn.Rejected):
        return {"rejected": out.reason}
    d = out.definition
    res = {"loaded": {"doc": json.loads(json.dumps(out.doc, default=str)), "name": d.name, "runs_in": d.runs_in,
                      "scope": json.loads(json.dumps(dispatch._scope(d), default=str)),
                      "agent": json.loads(json.dumps(dispatch._agent(d), default=str))}}
    try:
        json.dumps(out.doc)
    except TypeError as e:
        res["python_publish_error"] = f"{type(e).__name__}"
    return res


CASES: list[dict] = []


def case(name: str, text: str, *, xr: str = "gate-triage", owner: str = OWNER, reserved=tuple(BUNDLED), group: str = "") -> dict:
    c = {"name": name, "group": group, "text": text, "xr": xr, "owner": owner, "reserved": list(reserved),
         "python": decide(text, xr, owner, reserved)}
    CASES.append(c)
    return c


def dump(doc) -> str:
    return yaml.safe_dump(doc, sort_keys=False)


def mutate(name: str, fn, *, group: str = "schema", xr: str = "gate-triage", owner: str = OWNER, text_fn=None) -> None:
    d = copy.deepcopy(base())
    fn(d)
    case(name, dump(d), group=group, xr=xr, owner=owner)


def drop(*path):
    def f(d):
        for p in path[:-1]:
            d = d[p]
        del d[path[-1]]
    return f


def put(path, value):
    def f(d):
        for p in path[:-1]:
            d = d[p]
        d[path[-1]] = value
    return f


